// invoice_calc.js
const qty = 1;
const unitPrice = 25000; // dalam rupiah
const amount = qty * unitPrice;
const subtotal = amount;
const total = subtotal;
console.log("Qty:", qty);
console.log("Unit Price:", unitPrice);
console.log("Amount:", amount);
