// invoice_multi_items.js
const items = [
  { name: "VPS", qty: 1, unitPrice: 25000 },
  // Tambahkan item lain di sini, contoh:
  // { name: "Domain", qty: 1, unitPrice: 50000 },
];

const amounts = items.map(it => ({ ...it, amount: it.qty * it.unitPrice }));
const subtotal = amounts.reduce((sum, it) => sum + it.amount, 0);
const total = subtotal; // contoh: tanpa pajak/fee

console.log("Daftar item:");
amounts.forEach(it => {
  console.log(it.name, "Qty:", it.qty, "Unit:", it.unitPrice, "Amount:", it.amount);
});
console.log("Subtotal:", subtotal);
console.log("Total:", total);
